namespace Gordic.Ada.WebClient {

    var gcontent = Decorators.gcontent;

    @gcontent

    export class GAkcePolozkyEDSDetail extends GContentBase implements IGContent {

        public AkceFiltrDto: Gordic.Ada.Interface.GAgDokladyFilterDto;
        public modelEDS: Gordic.Ada.Interface.GPolozkaEDSDto;
        private priz_blok_ip: boolean;

//        private globals = Gordic.Ada.Globals.GAdaGlobals;
        private readonly globals: Gordic.Ada.WebClient.DTO.GAdaGlobalsDto;

        //---------------------------------------------------------------
        // Inicializace formuláře
        onContentReady() {

            var that = this;

            that.actions.addRange({                                                                                     // přidání akcí

                actOK: {
                    caption: "Ok",                                                                                      // OK
                    icon: "",                                                                                           // ikona 
                    visible: ((that.priz_blok_ip == false) && ((that.globals.Param_Editace_EDS == Gordic.Ada.Interface.PristupKEditaciEnum.Ano) || ((that.globals.Param_Editace_EDS == Gordic.Ada.Interface.PristupKEditaciEnum.Dle_Detailu) && (that.globals.Param_Akce_Editace_TP!)))), //true,                                                                                      // vždy viditelné
                    enabled: ((that.priz_blok_ip == false) && ((that.globals.Param_Editace_EDS == Gordic.Ada.Interface.PristupKEditaciEnum.Ano) || ((that.globals.Param_Editace_EDS == Gordic.Ada.Interface.PristupKEditaciEnum.Dle_Detailu) && (that.globals.Param_Akce_Editace_TP!)))),                                                                                      
                    run: function () {
                        that.closing(true) 
                    }
                },
                actZrusit: {
                    caption: "Zrušit",                                                                                  // popis
                    icon: "gi-window-close",                                                                            // ikona 
                    visible: true,                                                                                      // vždy viditelné
                    enabled: true,                                                                                      // vždy spustitelné
                    run: function () {
                        that.closing(false) 
                    }
                }
            });

            //*******************************************************
            // P ř i d á v á n í   a k c í   d o   m e n u   b a r u
            this.menuBar([

            ]);
            this.commandBar([
                { action: that.actions.actOK, favorite: true, primary: true },                                                         // Ok
                { action: that.actions.actZrusit, favorite: true },                                                     // Zrušit
            ]);

            
            // *****************************
            //    Formulář tabu
            var detailEDSForm = new Gordic.Forms.Form({ name: "detailEDS", layoutDescriptor: "L4M4S2 L-3-9-0 M-3-9-0 S-12-12-0" })
                .addRow(that.globals.BAR_Typ_Inst == Interface.SrvTypIntalaceEnum.MO ? "Číslo pol. plánu" : "Číslo akce").addField("gstringbox", "w-12", { disabled: true, name: "cislo" })
                .addRow("Projekt EDS").addField("gselectbox", Gordic.Prefabs.Select.srvsxpf(), { name: "id_eds", disabled: (that.modelEDS.id_eds == "" ? false : true), dropdown: false, model: "model.id_eds = value.xpf_pf", validators: [new Gordic.Validators.Required()] })
                .addRow("Aktivita").addField("gselectbox", Gordic.Prefabs.Select.gincakt(), { name: "aktivita", dropdown: true, model: "model.aktivita = value.aktivita", serverFilters: { aktivita: [100, 500] }, validators: [new Gordic.Validators.Required()] })
                ;
            
            $("<div class='js-detailEDS'>").appendTo(that.element).gform("createFrom", detailEDSForm, ).findFields().gfield("model", "apply", that.modelEDS);
            //that.findFields(".ui-tucne").find("input").addClass("bold");

            if ((that.priz_blok_ip == true) || (that.globals.Param_Editace_EDS == Gordic.Ada.Interface.PristupKEditaciEnum.Ne) || ((that.globals.Param_Editace_EDS == Gordic.Ada.Interface.PristupKEditaciEnum.Dle_Detailu) && (!that.globals.Param_Akce_Editace_TP))) {
                var fields = this.findFields(); // všechny políčka
                fields.findFields().gfield("option", "disabled", true) // vždy enabled
            }

         };

        //---------------------------------------------------------------
        // Zavírání formuláře
        closing( provest ) {
            if (provest == true) {
                var $cDiv = $(this.contentDiv);
                //this.contentDiv.showFlash({ label: 'Ukladam akci ' + cislo });
                if ($cDiv.findForms().gform("isValid", true)) {
                    //var dto = {};
                    $cDiv.findFields().gfield("model", "collect", this.modelEDS);
                    $cDiv.findFields().gfield("confirm");

                    this.close({ data: this.modelEDS });                                  // při zavírání posílanám zpět objekt
                }
            }
            else {
                this.close({ data: null });                                  // při zavírání posílanám zpět objekt
            }
        }
    }
}